/**
 * EmptyState, ErrorState, Skeleton (design-system §5.3).
 *
 * Each `ErrorState` status is asserted separately, and asserted to be *distinct*: collapsing
 * 401 and 403 into one message tells a user to sign in again when the real answer is that
 * their role doesn't include the data — a support ticket generated by a UI shortcut.
 */
import { render, screen } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import { EmptyState, ErrorState, Skeleton } from '../src/components/States';
import { DocumentIcon } from '../src/components/icons-console';

describe('EmptyState', () => {
  it('renders just a title when that is all it is given', () => {
    const { container } = render(<EmptyState title="No invoices yet" />);
    expect(screen.getByText('No invoices yet')).toHaveClass('janso-state__title');
    expect(container.querySelector('.janso-state__icon')).toBeNull();
    expect(container.querySelector('.janso-state__body')).toBeNull();
    expect(container.querySelector('.janso-state__action')).toBeNull();
  });

  it('renders the icon, body and action when given', () => {
    const { container } = render(
      <EmptyState
        icon={<DocumentIcon />}
        title="No invoices yet"
        body="Post your first invoice to see it here."
        action={<button type="button">New invoice</button>}
      />,
    );
    expect(container.querySelector('.janso-state__icon svg')).not.toBeNull();
    expect(screen.getByText('Post your first invoice to see it here.')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'New invoice' })).toBeInTheDocument();
  });

  it('hides a decorative icon from assistive tech', () => {
    const { container } = render(<EmptyState icon={<DocumentIcon />} title="Nothing here" />);
    expect(container.querySelector('.janso-state__icon')).toHaveAttribute('aria-hidden', 'true');
  });
});

const STATUSES = [401, 403, 422, 500] as const;

describe('ErrorState', () => {
  it.each(STATUSES)('announces %i as an alert with the danger triplet and an icon', (status) => {
    const { container } = render(<ErrorState status={status} />);
    const alert = screen.getByRole('alert');
    expect(alert).toHaveAttribute('data-tone', 'danger');
    expect(alert).toHaveClass('janso-state--error');
    // Status is never colour alone (design-system §2.4).
    expect(container.querySelector('.janso-state__icon svg')).not.toBeNull();
    expect(alert).not.toBeEmptyDOMElement();
  });

  it('tells a 401 to sign in again', () => {
    render(<ErrorState status={401} />);
    expect(screen.getByText('Your session has ended')).toBeInTheDocument();
    expect(screen.getByText(/Sign in again/)).toBeInTheDocument();
  });

  it('tells a 403 it is a permission problem, not a session problem', () => {
    render(<ErrorState status={403} />);
    expect(screen.getByText("You don't have access to this")).toBeInTheDocument();
    expect(screen.getByText(/role does not include this data/)).toBeInTheDocument();
  });

  it('points a 422 at the rejected fields', () => {
    render(<ErrorState status={422} />);
    expect(screen.getByText("We couldn't accept those details")).toBeInTheDocument();
    expect(screen.getByText(/Check the highlighted fields/)).toBeInTheDocument();
  });

  it('tells a 500 that nothing was changed', () => {
    render(<ErrorState status={500} />);
    expect(screen.getByText('Something went wrong')).toBeInTheDocument();
    expect(screen.getByText(/Nothing was changed/)).toBeInTheDocument();
  });

  it('gives each status its own copy', () => {
    const titles = STATUSES.map((status) => {
      const { container, unmount } = render(<ErrorState status={status} />);
      const title = container.querySelector('.janso-state__title')?.textContent ?? '';
      unmount();
      return title;
    });
    expect(new Set(titles).size).toBe(STATUSES.length);
  });

  it('adds server detail beside the intended copy, never instead of it', () => {
    const { container } = render(<ErrorState status={422} detail="posting_date is closed" />);
    expect(container.querySelector('.janso-state__title')).toHaveTextContent(
      "We couldn't accept those details",
    );
    expect(screen.getByText('posting_date is closed')).toHaveClass('janso-state__detail');
  });

  it('omits the detail line and action when not given', () => {
    const { container } = render(<ErrorState status={500} />);
    expect(container.querySelector('.janso-state__detail')).toBeNull();
    expect(container.querySelector('.janso-state__action')).toBeNull();
  });

  it('renders a retry action when given', () => {
    render(<ErrorState status={500} action={<button type="button">Try again</button>} />);
    expect(screen.getByRole('button', { name: 'Try again' })).toBeInTheDocument();
  });
});

describe('Skeleton', () => {
  it('is hidden from assistive tech — a reader should hear content, not grey bars', () => {
    const { container } = render(<Skeleton />);
    expect(container.querySelector('.janso-skeleton')).toHaveAttribute('aria-hidden', 'true');
  });

  it('renders three lines by default', () => {
    const { container } = render(<Skeleton />);
    expect(container.querySelectorAll('.janso-skeleton__line')).toHaveLength(3);
    expect(container.querySelector('.janso-skeleton')).toHaveAttribute('data-lines', '3');
  });

  it('renders the requested number of lines', () => {
    const { container } = render(<Skeleton lines={5} />);
    expect(container.querySelectorAll('.janso-skeleton__line')).toHaveLength(5);
  });

  it('never renders an empty placeholder for a nonsensical count', () => {
    const { container } = render(<Skeleton lines={0} />);
    expect(container.querySelectorAll('.janso-skeleton__line')).toHaveLength(1);
    expect(container.querySelector('.janso-skeleton')).toHaveAttribute('data-lines', '1');
  });

  it('applies a caller width, and none by default', () => {
    const { container: sized } = render(<Skeleton width="12rem" />);
    expect(skeletonRoot(sized)?.style.width).toBe('12rem');

    const { container: plain } = render(<Skeleton />);
    expect(skeletonRoot(plain)?.style.width).toBe('');
  });
});

/** The skeleton root, typed, so the width assertions above read as one line each. */
function skeletonRoot(root: HTMLElement): HTMLElement | null {
  return root.querySelector<HTMLElement>('.janso-skeleton');
}
